window.LD=window.LD||{};window.LD["party/p3"]={"id":"p3","name":"The Thunder of Frosthold","poss":"The Thunder of Frosthold's","members":["h5","h3","h4","h15"],"leader":"h5","morale":96,"disposition":"territorial","motto":"Sing along or get out.","banner":{"c1":"#2b2b33","c2":"#2f9e9e","emblem":"bolt"},"loc":"frosthold","loc_name":"Frosthold","goal":{"text":"to earn 550 silver between them before the season ends","kind":"purse","done":82,"progress":"1,023 silver, past the 550 aimed for","missed":false,"crew":"The Thunder of Frosthold","party":"p3"},"vows":[{"text":"to die rich","day":31,"state":"kept","ended":90,"through":true,"progress":"kept on day 30 of season 3","crew":"The Thunder of Frosthold","party":"p3"}],"doing":"last seen on the road to Ironhaven","progress":null,"today":["XP: Morwen +52, Duren +50, Pickles +42, Rook +42.","Coin between them: -16 silver (curio stall 15, readings 1, food 1).","Ate 4 rations.","Pickles: new gear, Ram's-Horn Drinking Cup."],"fights_today":[],"why":null,"founded_day":1,"founded_season":1,"disbanded":null,"anthem":null,"renown":294,"season":{"wins":14,"bosses":0,"floors":8,"gold":0,"deaths":0,"fled":0,"pvp_wins":0,"pvp_losses":0,"renown":0,"days":30,"arguments":5},"career":{"wins":30,"bosses":1,"floors":21,"gold":0,"deaths":0,"fled":2,"pvp_wins":0,"pvp_losses":0,"renown":0,"days":90,"arguments":17},"former":[],"fallen":[],"travel":{"from":"frosthold","to":"ironhaven","left":2,"total":3,"dest":"ironhaven","counted":true},"wagon":{"kind":"donkey_cart","name":"Wheelie","label":"donkey cart","seats":2,"haul":28,"comfort":1,"since":33,"desc":"Rattles. Gets there.","moves":true,"puller":{"kind":"donkey","name":"Bartholomew","label":"donkey","colour":"cream","owner":null},"paid":[["Duren",14],["Rook",13],["Pickles",7]]},"pace_gap":38,"rels":[{"party":"p4","score":96},{"party":"p6","score":34},{"party":"p1","score":15}],"events":[{"id":"e977","day":25,"season":1,"sday":25,"kind":"delve_day","imp":1,"text":"The Thunder of Frosthold works floor 2 of Frostspire at a steady pace: 3 rooms (the icicle porch, the yeti's writing desk, the ice-locked armoury).","heroes":["h5","h3","h4","h15"],"parties":["p3"],"loc":"frostspire","pace":"steady","stats":{"rooms":3,"size":4,"floor":2,"traps":1,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":["wild_footprint_desk"]}},{"id":"e978","day":25,"season":1,"sday":25,"kind":"ambush","imp":2,"text":"The Thunder of Frosthold wakes to 3 Ice Wraiths in camp on floor 2 of Frostspire in the middle of the night, and cuts them down. Three ice wraiths went down together, and they have Morwen's Nature's Wrath to thank. Duren found the weak spot first and kept hitting it. Morwen gave the victory speech nobody asked for. \"That was SO fun!\" says Morwen. Loot: 6 ectoplasm, 6 wraith-frost, 2 frost crystals.","heroes":["h5","h3","h4","h15"],"parties":["p3"],"loc":"frostspire","fight":"f81","foes":["ice_wraith","ice_wraith","ice_wraith"],"where":"at their camp on floor 2 of Frostspire, in the middle of the night","won":true,"close":false,"shape":"night","reworded":-12},{"id":"e1004","day":25,"season":1,"sday":25,"kind":"talent","imp":1,"text":"Rook teaches Pickles the sign for 'tea'. Pickles now uses it constantly. Hand Signs, the way the drill-yards teach it.","heroes":["h15","h4"],"parties":["p3"],"loc":"frostspire","skill":"hand_signs"},{"id":"e1025","day":26,"season":1,"sday":26,"kind":"delve_day","imp":1,"text":"The Thunder of Frosthold works floor 2 of Frostspire at a steady pace: 5 rooms (the sentries' bunks, the golem's niche, the hall of frozen explorers and 2 more).","heroes":["h5","h3","h4","h15"],"parties":["p3"],"loc":"frostspire","pace":"steady","stats":{"rooms":5,"size":4,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":1,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":3,"wild":[]}},{"id":"e1028","day":26,"season":1,"sday":26,"kind":"bond","imp":3,"text":"The Coin of Thornwall and The Thunder of Frosthold are rivals now, starting with Brix and Pickles.","heroes":["h1","h4"],"parties":["p6","p3"],"bond":"rivals"},{"id":"e1062","day":27,"season":1,"sday":27,"kind":"fight","imp":3,"text":"In the yeti dens on floor 2 of Frostspire, the Thunder of Frosthold is routed by 4 Yetis. Pickles was the last one out and the angriest about it. \"The dark wins a verse. Not the song,\" says Pickles. Rook has to be dragged out. Injured: Rook (sprained ankle).","heroes":["h5","h3","h4","h15"],"parties":["p3"],"loc":"frostspire","fight":"f87","foes":["yeti","yeti","yeti"],"where":"in the yeti dens on floor 2 of Frostspire","won":false,"close":true,"shape":"place","reworded":15},{"id":"e1063","day":27,"season":1,"sday":27,"kind":"delve_day","imp":1,"text":"The Thunder of Frosthold works floor 2 of Frostspire at a push pace: 5 rooms (the buried trunks, the gallery of ice figures, the white chapel and 2 more).","heroes":["h5","h3","h4","h15"],"parties":["p3"],"loc":"frostspire","pace":"push","stats":{"rooms":5,"size":4,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":1,"unwalked":1,"fights":1,"close":1,"gear":["common"],"fears":3,"wild":[]}},{"id":"e1064","day":27,"season":1,"sday":27,"kind":"delve_done","imp":3,"text":"The Thunder of Frosthold climbs out after 6 days with something unfriendly close behind and no wish to discuss it. They reached floor 2, worked through 23 rooms, turned up a sealed space off the sentry stair, the ice-locked armoury and the buried trunks, inked 38% of the map and split 121 silver on the way up. Frostspire now stands mostly unexplored (27%), every crew's chalk marks counted.","heroes":["h5","h3","h4","h15"],"parties":["p3"],"loc":"frostspire","days":6,"bottom":false,"rooms":["a sealed space off the sentry stair","the ice-locked armoury"],"gold":121,"out":"Driven out","turn":"routed"},{"id":"e1065","day":27,"season":1,"sday":27,"kind":"ability","imp":2,"text":"Morwen camps alone at Frostspire, and the forest, with nobody else to fuss over, fusses over him: a moss pillow, a fern blanket, and every ache gone by morning.","heroes":["h5"],"parties":["p3"],"loc":"frostspire","skill":"bed_of_moss","sk":"Bed of Moss","rule":true},{"id":"e1087","day":28,"season":1,"sday":28,"kind":"party_life","imp":1,"text":"Rook rides ahead, rides back, rides ahead again. Morwen, Duren and Pickles are not amused.","heroes":["h5","h3","h4","h15"],"parties":["p3"],"loc":"frostspire","wx":"snow"},{"id":"e1089","day":28,"season":1,"sday":28,"kind":"talent","imp":2,"text":"Pickles tries out a new verse on the party. Duren suggests a rhyme. It's in the song now.","heroes":["h4","h3"],"parties":["p3"],"loc":"whitepeak","skill":"packs_the_house","wx":"snow"},{"id":"e1090","day":28,"season":1,"sday":28,"kind":"ability","imp":1,"text":"At Whitepeak Pass, Rook re-rivets Morwen's pauldron and says nothing about how it got loose. Everyone sleeps easier.","heroes":["h15","h5"],"parties":["p3"],"loc":"whitepeak","skill":"evening_repairs","sk":"Evening Repairs","rule":true,"wx":"snow"},{"id":"e1108","day":28,"season":1,"sday":28,"kind":"talent","imp":1,"text":"Duren throws knucklebones by the fire and announces a good week. The crew is cheered, against its will.","heroes":["h3"],"parties":["p3"],"loc":"whitepeak","skill":"omens","wx":"snow"},{"id":"e1116","day":29,"season":1,"sday":29,"kind":"party_life","imp":1,"text":"Morwen, Duren and Pickles arrive at camp an hour behind Rook and find the good spot by the fire taken.","heroes":["h5","h3","h4","h15"],"parties":["p3"],"loc":"whitepeak"},{"id":"e1117","day":29,"season":1,"sday":29,"kind":"road","imp":2,"text":"Duren hauls a boulder up the verge and heaves it onto the Whitepeak Cairn, and the travellers around cheer at the thump.","heroes":["h3","h15","h4","h5"],"parties":["p3"],"road":"frosthold~whitepeak","road_rec":"r191"},{"id":"e1149","day":29,"season":1,"sday":29,"kind":"campfire","imp":1,"text":"Rook and Pickles plant a few seeds by the roadside and promise to check on them next time through.","heroes":["h15","h4"],"parties":["p3"],"loc":"frosthold"},{"id":"e1167","day":30,"season":1,"sday":30,"kind":"talent","imp":1,"text":"Morwen opens the spice tin and the boring stew becomes a different, much better stew. Spice Box all the way, Morwen insists.","heroes":["h5"],"parties":["p3"],"loc":"whitepeak","skill":"spice_box"},{"id":"e1229","day":31,"season":2,"sday":1,"kind":"road","imp":2,"text":"A country fair is packing up beside the road to Carrbridge, and Duren lends a shoulder to a stage, a tent and an ox. The stallholders give him 2 silver and a bag of leftover buns.","heroes":["h3","h15","h4","h5"],"parties":["p3"],"road":"carrbridge~saltmarrow","road_rec":"r205"},{"id":"e1241","day":31,"season":2,"sday":1,"kind":"boss_race","imp":3,"text":"Two crews, one boss. The Thunder of Frosthold and The Coin of Thornwall have both set out for Thornmere Ruins. The taverns are taking bets.","heroes":["h5","h3","h4","h15","h1","h8","h16"],"parties":["p3","p6"],"loc":"thornmere_ruins"},{"id":"e1251","day":31,"season":2,"sday":1,"kind":"campfire","imp":1,"text":"Morwen and Duren have shared a month of roads in The Thunder of Frosthold. Ask either one about the other and settle in for a story.","heroes":["h5","h3"],"parties":["p3"],"loc":"saltmarrow","wx":"storm"},{"id":"e1252","day":31,"season":2,"sday":1,"kind":"campfire","imp":1,"text":"Morwen and Pickles have a month of roads behind them in The Thunder of Frosthold, and a dozen stories nobody else is allowed to tell.","heroes":["h5","h4"],"parties":["p3"],"loc":"saltmarrow","wx":"storm"},{"id":"e1264","day":31,"season":2,"sday":1,"kind":"vow","imp":3,"text":"A vow from The Thunder of Frosthold: to die rich. Easy to say on day one.","heroes":["h5","h3","h4","h15"],"parties":["p3"]},{"id":"e1271","day":32,"season":2,"sday":2,"kind":"road","imp":3,"text":"The Collective write a song about Rook. It has seven verses, two choruses and five different endings, one for each of them.","heroes":["h15","h3","h4","h5"],"parties":["p3"],"road":"carrbridge~saltmarrow","traveller":"off_key","road_rec":"r217"},{"id":"e1311","day":33,"season":2,"sday":3,"kind":"wagon","imp":3,"text":"The Thunder of Frosthold buys a donkey cart in Carrbridge for 34 silver. It's called Wheelie now. Who paid: Duren 14, Rook 13, Pickles 7.","heroes":["h5","h3","h4","h15"],"parties":["p3"],"loc":"carrbridge"},{"id":"e1319","day":33,"season":2,"sday":3,"kind":"bar_fight","imp":5,"text":"BAR FIGHT at The Honest Toll! It starts when Brix insists the last round was already paid for, and within a minute Brix, Duren and Morwen are all in it. When the dust settles Brix is still swinging at nobody in particular, and Morwen is in the rain barrel. Jolly Mott bills Brix 15 silver for the furniture and bans them for three nights.","heroes":["h1","h3","h5"],"parties":["p6","p3"],"loc":"carrbridge"},{"id":"e1320","day":33,"season":2,"sday":3,"kind":"song","imp":3,"text":"\"The Ballad of Brix\" is new at The Honest Toll tonight. The song is about a tavern brawl in Carrbridge, more or less. By the third verse the whole room knows the words.","heroes":["h1"],"parties":["p6","p3"],"loc":"carrbridge","song":"s33_19"},{"id":"e1329","day":33,"season":2,"sday":3,"kind":"campfire","imp":1,"text":"A month in The Thunder of Frosthold together. Morwen and Rook know each other's snores, sorrows and orders by heart.","heroes":["h5","h15"],"parties":["p3"],"loc":"carrbridge"},{"id":"e1330","day":33,"season":2,"sday":3,"kind":"campfire","imp":1,"text":"Pickles and Rook have shared a month of roads in The Thunder of Frosthold. Ask either one about the other and settle in for a story.","heroes":["h4","h15"],"parties":["p3"],"loc":"carrbridge"},{"id":"e1332","day":33,"season":2,"sday":3,"kind":"campfire","imp":1,"text":"Pickles and Morwen invent a scoring system for snoring. Nobody else is consulted.","heroes":["h4","h5"],"parties":["p3"],"loc":"carrbridge"},{"id":"e1345","day":34,"season":2,"sday":4,"kind":"party_life","imp":1,"text":"Rook waits at every crossroads for Pickles to catch up, and says nothing very loudly.","heroes":["h5","h3","h4","h15"],"parties":["p3"],"loc":"carrbridge"},{"id":"e1346","day":34,"season":2,"sday":4,"kind":"road","imp":3,"text":"A stranger sits at a gate across the road to Bleakmarsh and demands a story for passage. Duren tells the best one he knows, and the stranger weeps, and writes it down.","heroes":["h3","h15","h4","h5"],"parties":["p3"],"road":"bleakmarsh~carrbridge","road_rec":"r236"},{"id":"e1360","day":34,"season":2,"sday":4,"kind":"meet","imp":2,"text":"Gorm and Duren swap stories in Bleakmarsh while The Scarlet Thorns and The Thunder of Frosthold swap rumours.","heroes":["h6","h9","h5","h3","h4","h15"],"parties":["p1","p3"],"loc":"bleakmarsh","wx":"rain"},{"id":"e1361","day":34,"season":2,"sday":4,"kind":"journey","imp":2,"text":"On the way to Bleakmarsh, The Thunder of Frosthold catches up with The Coin of Thornwall. The conversation turns to the best way to cook a rat and never recovers.","heroes":["h5","h3","h4","h15","h1","h8","h16"],"parties":["p3","p6"]},{"id":"e1403","day":35,"season":2,"sday":5,"kind":"party_life","imp":1,"text":"Pickles asks Rook if the view is nice up there. It is.","heroes":["h5","h3","h4","h15"],"parties":["p3"],"loc":"bleakmarsh","wx":"rain"},{"id":"e1407","day":35,"season":2,"sday":5,"kind":"meet","imp":2,"text":"The Coin of Thornwall spots The Thunder of Frosthold in Thornmere Ruins and takes the long way round. Half a day lost. Worth it.","heroes":["h1","h8","h16","h5","h3","h4","h15"],"parties":["p6","p3"],"loc":"thornmere_ruins","wx":"rain"},{"id":"e1422","day":36,"season":2,"sday":6,"kind":"delve","imp":1,"text":"The Thunder of Frosthold descends into Thornmere Ruins, partly explored (37%).","heroes":["h5","h3","h4","h15"],"parties":["p3"],"loc":"thornmere_ruins","wx":"rain"},{"id":"e1423","day":36,"season":2,"sday":6,"kind":"delve_day","imp":1,"text":"The Thunder of Frosthold works floor 2 of Thornmere Ruins at a steady pace: 3 rooms (a sealed space off the flooded side aisle, the reliquary niche, the brewhouse).","heroes":["h5","h3","h4","h15"],"parties":["p3"],"loc":"thornmere_ruins","pace":"steady","stats":{"rooms":3,"size":4,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]},"wx":"rain"},{"id":"e1424","day":36,"season":2,"sday":6,"kind":"ability","imp":2,"text":"Rook lies down on a rock at camp. Morwen has a word with the rock. It is moss now, and Rook sleeps like a baby.","heroes":["h5","h15"],"parties":["p3"],"loc":"thornmere_ruins","skill":"bed_of_moss","sk":"Bed of Moss","rule":true,"wx":"rain"},{"id":"e1434","day":36,"season":2,"sday":6,"kind":"meet","imp":1,"text":"The Coin of Thornwall and The Thunder of Frosthold cross paths in Thornmere Ruins. Nobody draws, but nobody turns their back either.","heroes":["h1","h8","h16","h5","h3","h4","h15"],"parties":["p6","p3"],"loc":"thornmere_ruins","wx":"rain"},{"id":"e1469","day":37,"season":2,"sday":7,"kind":"artifact","imp":3,"text":"Duren pockets a locket that will not open and will not be left behind in Thornmere Ruins. Duren feels stronger already.","heroes":["h3"],"parties":["p3"],"loc":"thornmere_ruins","wx":"rain"},{"id":"e1470","day":37,"season":2,"sday":7,"kind":"delve_day","imp":1,"text":"The Thunder of Frosthold works floor 2 of Thornmere Ruins at a steady pace: 3 rooms (a sealed space off the physic garden, the cloister walk, the buttery).","heroes":["h5","h3","h4","h15"],"parties":["p3"],"loc":"thornmere_ruins","pace":"steady","stats":{"rooms":3,"size":4,"floor":2,"traps":1,"sprung":1,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":["common"],"fears":0,"wild":[]},"wx":"rain"},{"id":"e1471","day":37,"season":2,"sday":7,"kind":"meet","imp":1,"text":"The Coin of Thornwall and The Thunder of Frosthold end up at the same fire in Thornmere Ruins. Nobody speaks. Everybody keeps a hand near a weapon.","heroes":["h1","h8","h16","h5","h3","h4","h15"],"parties":["p6","p3"],"loc":"thornmere_ruins","wx":"rain"},{"id":"e1474","day":37,"season":2,"sday":7,"kind":"talent","imp":1,"text":"Pickles sits up with Duren through a fever, talking about nothing. By morning Duren is sitting up and asking for breakfast. The words of Bedside Manner, half under her breath.","heroes":["h4","h3"],"parties":["p3"],"loc":"thornmere_ruins","skill":"bedside_manner","wx":"rain"},{"id":"e1488","day":38,"season":2,"sday":8,"kind":"delve_day","imp":1,"text":"The Thunder of Frosthold works floor 2 of Thornmere Ruins at a steady pace: 3 rooms (the sunken stair, the ossuary, the reliquary niche).","heroes":["h5","h3","h4","h15"],"parties":["p3"],"loc":"thornmere_ruins","pace":"steady","stats":{"rooms":3,"size":4,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":["common"],"fears":0,"wild":[]},"wx":"storm"},{"id":"e1497","day":38,"season":2,"sday":8,"kind":"meet","imp":1,"text":"The Thunder of Frosthold and The Coin of Thornwall camp within sight of each other in Thornmere Ruins and spend the night pretending not to watch.","heroes":["h5","h3","h4","h15","h1","h8","h16"],"parties":["p3","p6"],"loc":"thornmere_ruins","wx":"storm"},{"id":"e1513","day":39,"season":2,"sday":9,"kind":"delve_day","imp":1,"text":"The Thunder of Frosthold works floor 2 of Thornmere Ruins at a steady pace: 3 rooms (the abbot's lodging, the reed maze, the black pool).","heroes":["h5","h3","h4","h15"],"parties":["p3"],"loc":"thornmere_ruins","pace":"steady","stats":{"rooms":3,"size":4,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":1,"wild":[]},"wx":"storm"},{"id":"e1514","day":39,"season":2,"sday":9,"kind":"talent","imp":1,"text":"Duren takes off the Road-Eating Boots by the fire. They twitch, wanting to go.","heroes":["h3"],"parties":["p3"],"loc":"thornmere_ruins","wx":"storm"},{"id":"e1529","day":39,"season":2,"sday":9,"kind":"meet","imp":1,"text":"The Thunder of Frosthold and The Coin of Thornwall end up at the same fire in Thornmere Ruins. Nobody speaks. Everybody keeps a hand near a weapon.","heroes":["h5","h3","h4","h15","h1","h8","h16"],"parties":["p3","p6"],"loc":"thornmere_ruins","wx":"storm"},{"id":"e1532","day":39,"season":2,"sday":9,"kind":"talent","imp":1,"text":"Morwen reads the tracks round camp at dawn: a fox, a badger, and Pickles sleepwalking. Every druid learns Tracker sooner or later. Not every druid learns it like that.","heroes":["h5","h4"],"parties":["p3"],"loc":"thornmere_ruins","skill":"tracker","wx":"storm"},{"id":"e1538","day":40,"season":2,"sday":10,"kind":"fight","imp":3,"text":"It's 2 Sirens and 2 Bog Crawlers against the Thunder of Frosthold in the singing sump on floor 3 of Thornmere Ruins, and it isn't close. One Nature's Wrath from Morwen and four of them were on the ground. Loot: 1 gem, 5 sea grapes, 4 chitin.","heroes":["h5","h3","h4","h15"],"parties":["p3"],"loc":"thornmere_ruins","fight":"f122","foes":["siren","siren","bog_crawler"],"where":"in the singing sump on floor 3 of Thornmere Ruins","won":true,"close":false,"shape":"foe","reworded":-23,"wx":"storm"},{"id":"e1539","day":40,"season":2,"sday":10,"kind":"delve_day","imp":1,"text":"The Thunder of Frosthold works floor 3 of Thornmere Ruins at a steady pace: 4 rooms (the wellhead, the singing sump, the ossuary and 1 more).","heroes":["h5","h3","h4","h15"],"parties":["p3"],"loc":"thornmere_ruins","pace":"steady","stats":{"rooms":4,"size":4,"floor":3,"traps":1,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":1,"close":0,"gear":[],"fears":0,"wild":[]},"wx":"storm"},{"id":"e1561","day":40,"season":2,"sday":10,"kind":"meet","imp":1,"text":"The Thunder of Frosthold and The Coin of Thornwall cross paths in Thornmere Ruins. Nobody draws, but nobody turns their back either.","heroes":["h5","h3","h4","h15","h1","h8","h16"],"parties":["p3","p6"],"loc":"thornmere_ruins","wx":"storm"},{"id":"e1578","day":41,"season":2,"sday":11,"kind":"curse","imp":4,"text":"Something is wrong with The Thunder of Frosthold. Since Duren picked up Grandmother's Locket, nobody trusts anybody, and Duren won't put it down.","heroes":["h3"],"parties":["p3"],"loc":"thornmere_ruins","wx":"storm"},{"id":"e1587","day":41,"season":2,"sday":11,"kind":"sniped","imp":3,"text":"Word reaches The Thunder of Frosthold on floor 3 of Thornmere Ruins: The Coin of Thornwall killed Mother Thornmere today. Nobody says much. The side passages still need mapping.","heroes":["h5","h3","h4","h15","h1","h8","h16"],"parties":["p3","p6"],"loc":"thornmere_ruins","snipers":["h1","h8","h16"],"where":"inside","boss":"Mother Thornmere","in_fight":"f126","wx":"storm"},{"id":"e1608","day":41,"season":2,"sday":11,"kind":"delve_day","imp":1,"text":"The Thunder of Frosthold works floor 3 of Thornmere Ruins at a cautious pace: 3 rooms (the dormitory, the drowned crypt, the curtain of hair).","heroes":["h5","h3","h4","h15"],"parties":["p3"],"loc":"thornmere_ruins","pace":"cautious","stats":{"rooms":3,"size":4,"floor":3,"traps":1,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":1,"wild":[]},"wx":"storm"},{"id":"e1609","day":41,"season":2,"sday":11,"kind":"ability","imp":2,"text":"Morwen asks a hollow tree at Thornmere Ruins for a bed. The tree obliges, lined with moss and dry leaves. Morwen sleeps like a dormouse and wakes mended and cheerful.","heroes":["h5"],"parties":["p3"],"loc":"thornmere_ruins","skill":"bed_of_moss","sk":"Bed of Moss","rule":true,"wx":"storm"},{"id":"e1620","day":41,"season":2,"sday":11,"kind":"meet","imp":1,"text":"The Coin of Thornwall and The Thunder of Frosthold cross paths in Thornmere Ruins. Nobody draws, but nobody turns their back either.","heroes":["h1","h8","h16","h5","h3","h4","h15"],"parties":["p6","p3"],"loc":"thornmere_ruins","wx":"storm"},{"id":"e1629","day":41,"season":2,"sday":11,"kind":"talent","imp":2,"text":"Morwen finds the one dry hollow in a soaking wood and invites everyone in. (Bed of Moss, if anyone's asking.)","heroes":["h5"],"parties":["p3"],"loc":"thornmere_ruins","skill":"bed_of_moss","wx":"storm"},{"id":"e1630","day":41,"season":2,"sday":11,"kind":"campfire","imp":1,"text":"Morwen and Rook take the late watch together and argue happily about the best road to Ironhaven.","heroes":["h5","h15"],"parties":["p3"],"loc":"thornmere_ruins","wx":"storm"},{"id":"e1638","day":41,"season":2,"sday":11,"kind":"goal","imp":2,"text":"After a long night's talk, The Thunder of Frosthold settles on a goal: to finish the season as one of the top three parties.","heroes":["h5","h3","h4"],"parties":["p3"]},{"id":"e1658","day":42,"season":2,"sday":12,"kind":"delve_done","imp":3,"text":"Up the last steps after 7 days: The Thunder of Frosthold climbs into the sun and nobody says anything for a while. They came across a sealed space off the flooded side aisle, the reliquary niche, a sealed space off the physic garden and 4 more good rooms, reached the deepest floor, worked through 19 rooms, disarmed 1 trap, inked 38% of the map, came away with 201 silver between them and turned back because the rations would only just see them home. Not the trip they set out on, but a trip. Thornmere Ruins now stands mostly explored (88%), every crew's chalk marks counted.","heroes":["h5","h3","h4","h15"],"parties":["p3"],"loc":"thornmere_ruins","days":7,"bottom":true,"rooms":["a sealed space off the flooded side aisle","the reliquary niche"],"gold":201,"turn":"supplies","wx":"storm"},{"id":"e1673","day":43,"season":2,"sday":13,"kind":"talent","imp":1,"text":"Duren wakes with a sprig of thyme behind one ear and no idea how it got there. Chalk it up to Bed of Moss.","heroes":["h5","h3"],"parties":["p3"],"loc":"bleakmarsh","skill":"bed_of_moss","wx":"storm"},{"id":"e1674","day":43,"season":2,"sday":13,"kind":"ability","imp":2,"text":"Rook works through the crew's gear by firelight at Bleakmarsh, one buckle at a time. Pickles wakes in armour that fits again.","heroes":["h15","h4"],"parties":["p3"],"loc":"bleakmarsh","skill":"evening_repairs","sk":"Evening Repairs","rule":true,"wx":"storm"},{"id":"e1675","day":43,"season":2,"sday":13,"kind":"night","imp":1,"text":"Pickles trades a ration with a stranger who wasn't there at dusk and isn't there at dawn. The trinket stays.","heroes":["h5","h3","h4","h15"],"parties":["p3"],"loc":"bleakmarsh","wx":"storm"},{"id":"e1698","day":43,"season":2,"sday":13,"kind":"argument","imp":4,"text":"Morwen and Rook have had the same argument three times now. This time Morwen just walks away mid-sentence, which is worse. The Thunder of Frosthold is splitting into camps.","heroes":["h5","h15"],"parties":["p3"]},{"id":"e1728","day":44,"season":2,"sday":14,"kind":"talent","imp":2,"text":"Duren lifts the Carrbridge tavern into a rousing chorus. Three tables start a dance. Crescendo all the way, Duren insists.","heroes":["h3"],"parties":["p3"],"loc":"carrbridge","skill":"crescendo"},{"id":"e1731","day":44,"season":2,"sday":14,"kind":"ability","imp":1,"text":"Pickles plays a Carrbridge tavern so packed the landlord opens the windows so the street can hear. 50 silver, a lot of new fans and a very happy party.","heroes":["h4"],"parties":["p3"],"loc":"carrbridge","skill":"packs_the_house","sk":"Packs the House","rule":true},{"id":"e1754","day":45,"season":2,"sday":15,"kind":"road","imp":3,"text":"A folded note arrives for Pickles by way of Lark, in Rook's hand. The courier is gone before it is read.","heroes":["h4","h15","h3","h5"],"parties":["p3"],"road":"carrbridge~ironhaven","traveller":"lark","road_rec":"r290"},{"id":"e1764","day":45,"season":2,"sday":15,"kind":"talent","imp":1,"text":"Pickles dances between two crossed swords at the Ironhaven tavern. The applause rattles the shutters. Sword Dancer, the way the drill-yards teach it.","heroes":["h4"],"parties":["p3"],"loc":"ironhaven","skill":"sword_dancer","wx":"fog"},{"id":"e1765","day":45,"season":2,"sday":15,"kind":"bar_fight","imp":5,"text":"BAR FIGHT at The Gilded Flagon! It starts when Duren says something about somebody's mother, and within a minute Morwen, Pickles and Duren are all in it. Pickles is the last one standing on a table; Morwen wakes up under one. Madame Ostrava bills Duren 21 silver for the furniture and bans him for three nights.","heroes":["h5","h4","h3"],"parties":["p3"],"loc":"ironhaven","wx":"fog"},{"id":"e1766","day":45,"season":2,"sday":15,"kind":"song","imp":3,"text":"\"When the Thunder of Frosthold Came Down\" opens at The Gilded Flagon tonight. The subject is a tavern brawl in Ironhaven, with the boring bits left out. The bard needs only one cup of courage, and gets four from the crowd.","heroes":["h5"],"parties":["p3"],"loc":"ironhaven","song":"s45_21","wx":"fog"},{"id":"e1776","day":45,"season":2,"sday":15,"kind":"argument","imp":2,"text":"Duren and Pickles of The Thunder of Frosthold have a shouting match about the party's name.","heroes":["h3","h4"],"parties":["p3"]},{"id":"e1799","day":46,"season":2,"sday":16,"kind":"party_life","imp":1,"text":"By the third crossroads Rook has stopped waiting and started complaining about the wait.","heroes":["h5","h3","h4","h15"],"parties":["p3"],"loc":"ironhaven","wx":"fog"},{"id":"e1837","day":47,"season":2,"sday":17,"kind":"road","imp":3,"text":"Duren is asked to check Ines's latest map. The compass rose is in the wrong corner, and the sea in the wrong place, but the hills are excellent.","heroes":["h3","h15","h4","h5"],"parties":["p3"],"road":"frosthold~ironhaven","traveller":"ines","road_rec":"r306"},{"id":"e1872","day":48,"season":2,"sday":18,"kind":"curse","imp":2,"text":"Duren still won't put down Grandmother's Locket. 7 days now. The others have stopped asking.","heroes":["h3"],"parties":["p3"],"loc":"ironhaven"},{"id":"e1901","day":49,"season":2,"sday":19,"kind":"ability","imp":2,"text":"Rook hums over the coals at Whitepeak Pass and tempers a bent greave in the stream. It rings like a bell afterwards.","heroes":["h15"],"parties":["p3"],"loc":"whitepeak","skill":"evening_repairs","sk":"Evening Repairs","rule":true,"wx":"storm"},{"id":"e1937","day":50,"season":2,"sday":20,"kind":"road","imp":3,"text":"Pickles sits with a hooded pilgrim by the Snow Lamp and shares bread, and the pilgrim murmurs a blessing in a tongue Pickles nearly understands. She leaves 2 copper in the tin.","heroes":["h4","h15","h3","h5"],"parties":["p3"],"road":"frostspire~whitepeak","road_rec":"r328"},{"id":"e1946","day":50,"season":2,"sday":20,"kind":"talent","imp":1,"text":"Duren finds moonpetal growing in a crack at Frostspire, glowing faintly. It's worth more than the fight was.","heroes":["h3"],"parties":["p3"],"loc":"frostspire","skill":"herbalism","wx":"snow"},{"id":"e1965","day":51,"season":2,"sday":21,"kind":"delve","imp":1,"text":"The Thunder of Frosthold descends into Frostspire, mostly unexplored (27%), map in hand.","heroes":["h5","h3","h4","h15"],"parties":["p3"],"loc":"frostspire","wx":"snow"},{"id":"e1966","day":51,"season":2,"sday":21,"kind":"fight","imp":3,"text":"The Thunder of Frosthold handles 3 Yetis and a Frost Wolf in the yeti dens on floor 2 of Frostspire without much fuss. Morwen's Nature's Wrath put poison in the yeti, and it did its slow work. Without Rook's Inspire, this goes differently. Loot: 25 pelts, 4 fangs & claws, 2 wolf haunches.","heroes":["h5","h3","h4","h15"],"parties":["p3"],"loc":"frostspire","fight":"f144","foes":["frost_wolf","yeti","yeti"],"where":"in the yeti dens on floor 2 of Frostspire","won":true,"close":false,"shape":"plain","reworded":-18,"wx":"snow"},{"id":"e1967","day":51,"season":2,"sday":21,"kind":"delve_day","imp":1,"text":"The Thunder of Frosthold works floor 2 of Frostspire at a steady pace: 2 rooms (the yeti dens, a hidden room behind the yeti dens).","heroes":["h5","h3","h4","h15"],"parties":["p3"],"loc":"frostspire","pace":"steady","stats":{"rooms":2,"size":4,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":1,"close":0,"gear":["common"],"fears":0,"wild":[]},"wx":"snow"},{"id":"e1968","day":51,"season":2,"sday":21,"kind":"ability","imp":2,"text":"The ground at Frostspire is all roots and rocks until Morwen hums to it. It softens into one long green mattress for the crew, who wake up healed and refusing to move.","heroes":["h5"],"parties":["p3"],"loc":"frostspire","skill":"bed_of_moss","sk":"Bed of Moss","rule":true,"wx":"snow"},{"id":"e2007","day":52,"season":2,"sday":22,"kind":"delve_day","imp":1,"text":"The Thunder of Frosthold works floor 2 of Frostspire at a push pace: 2 rooms (the yeti's nest of shinies, the draught hole).","heroes":["h5","h3","h4","h15"],"parties":["p3"],"loc":"frostspire","pace":"push","stats":{"rooms":2,"size":4,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":1,"unwalked":1,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]},"wx":"snow"},{"id":"e2044","day":53,"season":2,"sday":23,"kind":"delve_day","imp":1,"text":"The Thunder of Frosthold works floor 2 of Frostspire at a push pace: 1 room (the draught hole).","heroes":["h5","h3","h4","h15"],"parties":["p3"],"loc":"frostspire","pace":"push","stats":{"rooms":1,"size":4,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":1,"unwalked":1,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]}},{"id":"e2045","day":53,"season":2,"sday":23,"kind":"delve_done","imp":3,"text":"Frostspire is behind The Thunder of Frosthold now: 3 days down there, and the sky looks enormous. They made it to floor 2, came across a hidden room behind the yeti dens and the yeti's nest of shinies, worked through 3 rooms, split 91 silver on the way up and turned back because the way on beat them twice, and they mean to come back with more.","heroes":["h5","h3","h4","h15"],"parties":["p3"],"loc":"frostspire","days":3,"bottom":false,"rooms":["a hidden room behind the yeti dens","the yeti's nest of shinies"],"gold":91,"turn":"blocked"},{"id":"e2066","day":53,"season":2,"sday":23,"kind":"argument","imp":3,"text":"Pickles and Rook are not speaking. It's about whether the last fight was a retreat or a 'tactical repositioning'. It's never really about whether the last fight was a retreat or a 'tactical repositioning'.","heroes":["h4","h15"],"parties":["p3"]},{"id":"e2069","day":53,"season":2,"sday":23,"kind":"campfire","imp":1,"text":"Pickles lets Rook win at arm-wrestling. Rook knows, and both let it stand.","heroes":["h4","h15"],"parties":["p3"],"loc":"frostspire"},{"id":"e2105","day":55,"season":2,"sday":25,"kind":"curse","imp":2,"text":"Duren snaps at a barkeep over nothing, then stares at Grandmother's Locket for an hour. The curse is winning, for now.","heroes":["h3"],"parties":["p3"],"loc":"whitepeak","wx":"snow"},{"id":"e2109","day":55,"season":2,"sday":25,"kind":"party_life","imp":1,"text":"Rook waits at every crossroads for Pickles to catch up, and says nothing very loudly.","heroes":["h5","h3","h4","h15"],"parties":["p3"],"loc":"whitepeak","wx":"snow"},{"id":"e2132","day":55,"season":2,"sday":25,"kind":"ability","imp":2,"text":"A Frosthold landlord books Pickles for one song and gets nine. 54 silver, a free supper, and a queue of people wanting the words written down.","heroes":["h4"],"parties":["p3"],"loc":"frosthold","skill":"packs_the_house","sk":"Packs the House","rule":true,"wx":"snow"},{"id":"e2136","day":55,"season":2,"sday":25,"kind":"campfire","imp":1,"text":"Pickles buys Rook a wine. Then another. Then the conversation gets honest.","heroes":["h4","h15"],"parties":["p3"],"loc":"frosthold","wx":"snow"},{"id":"e2142","day":56,"season":2,"sday":26,"kind":"curse","imp":5,"text":"Father Hoarfrost takes Grandmother's Locket from Duren's shaking hands, says some very old words over it, and breaks it. 52 silver, and worth every coin.","heroes":["h3"],"parties":["p3"],"loc":"frosthold","wx":"snow"},{"id":"e2154","day":56,"season":2,"sday":26,"kind":"ability","imp":1,"text":"Morwen pats the ground at camp and moss creeps up into soft green beds. Everyone wakes mended and in a good mood.","heroes":["h5"],"parties":["p3"],"loc":"whitepeak","skill":"bed_of_moss","sk":"Bed of Moss","rule":true,"wx":"snow"},{"id":"e2162","day":56,"season":2,"sday":26,"kind":"argument","imp":1,"text":"The Thunder of Frosthold spends the evening listening to Rook and Pickles argue about Rook's snoring.","heroes":["h15","h4"],"parties":["p3"]},{"id":"e2174","day":57,"season":2,"sday":27,"kind":"talent","imp":2,"text":"Duren brews something green and bitter for Rook's cough. Rook hates it. The cough's gone by morning. Herbalism: a ranger's patience, mostly.","heroes":["h3","h15"],"parties":["p3"],"loc":"frostspire","skill":"herbalism","wx":"snow"},{"id":"e2186","day":57,"season":2,"sday":27,"kind":"argument","imp":4,"text":"Enough is enough: Duren tells Rook exactly what everyone in The Thunder of Frosthold has been thinking. Nobody sleeps.","heroes":["h15","h3"],"parties":["p3"]},{"id":"e2188","day":57,"season":2,"sday":27,"kind":"talent","imp":1,"text":"Morwen whittles a tiny wolf for Pickles by the fire. Pickles calls it silly and keeps it in a breast pocket.","heroes":["h5","h4"],"parties":["p3"],"loc":"frostspire","skill":"whittler","wx":"snow"},{"id":"e2195","day":58,"season":2,"sday":28,"kind":"delve","imp":1,"text":"The Thunder of Frosthold descends into Frostspire, mostly unexplored (29%), map in hand.","heroes":["h5","h3","h4","h15"],"parties":["p3"],"loc":"frostspire","wx":"storm"},{"id":"e2196","day":58,"season":2,"sday":28,"kind":"fight","imp":1,"text":"A Yeti, an Ice Wraith and a Frost Wolf fall to the Thunder of Frosthold in a stair of blue glass cut in the wall, rimed with frost on floor 1 of Frostspire. Nature's Wrath caught two of them in one go. That was Morwen. Saga of Fury did more for this fight than the scoreboard shows. That was Pickles. Loot: 9 pelts, 3 ectoplasm, 2 fangs & claws.","heroes":["h5","h3","h4","h15"],"parties":["p3"],"loc":"frostspire","fight":"f166","foes":["yeti","ice_wraith","frost_wolf"],"where":"in a stair of blue glass cut in the wall, rimed with frost on floor 1 of Frostspire","won":true,"close":false,"shape":"foe","reworded":1,"wx":"storm"},{"id":"e2197","day":58,"season":2,"sday":28,"kind":"fight","imp":2,"text":"Duren hits hardest as the Thunder of Frosthold makes short work of 2 Frost Wolves and 2 Yetis in the yeti's writing desk on floor 1 of Frostspire. The fight turned on Duren's Dissonance. Loot: 21 pelts, 2 wolf haunches, 2 fangs & claws.","heroes":["h5","h3","h4","h15"],"parties":["p3"],"loc":"frostspire","fight":"f167","foes":["frost_wolf","frost_wolf","yeti"],"where":"in the yeti's writing desk on floor 1 of Frostspire","won":true,"close":false,"shape":"hero","reworded":-22,"wx":"storm"},{"id":"e2198","day":58,"season":2,"sday":28,"kind":"delve_day","imp":1,"text":"The Thunder of Frosthold works floor 2 of Frostspire at a push pace: 3 rooms (a stair of blue glass cut in the wall, rimed with frost, the yeti's writing desk, the draught hole).","heroes":["h5","h3","h4","h15"],"parties":["p3"],"loc":"frostspire","pace":"push","stats":{"rooms":3,"size":4,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":1,"unwalked":1,"fights":2,"close":0,"gear":[],"fears":0,"wild":[]},"wx":"storm"},{"id":"e2199","day":58,"season":2,"sday":28,"kind":"night","imp":2,"text":"Morwen tells a ghost story by the fire on floor 2 of Frostspire. Duren laughs at it, then moves their bedroll closer to the others.","heroes":["h5","h3","h4","h15"],"parties":["p3"],"loc":"frostspire","wx":"storm"},{"id":"e2219","day":58,"season":2,"sday":28,"kind":"campfire","imp":2,"text":"Duren brings back a brace of rabbits for the pot. Morwen cooks them. Teamwork.","heroes":["h3","h5"],"parties":["p3"],"loc":"frostspire","wx":"storm"},{"id":"e2232","day":59,"season":2,"sday":29,"kind":"delve_day","imp":1,"text":"The Thunder of Frosthold works floor 2 of Frostspire at a steady pace: 1 room (the draught hole).","heroes":["h5","h3","h4","h15"],"parties":["p3"],"loc":"frostspire","pace":"steady","stats":{"rooms":1,"size":4,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":1,"unwalked":1,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]},"wx":"storm"},{"id":"e2233","day":59,"season":2,"sday":29,"kind":"delve_done","imp":1,"text":"The Thunder of Frosthold climbs the last ladder after 2 days, and the sitting down happens at the top of it. They made it to floor 2, worked through 2 rooms and turned back because the way on beat them twice, and they mean to come back with more.","heroes":["h5","h3","h4","h15"],"parties":["p3"],"loc":"frostspire","days":2,"bottom":false,"rooms":[],"gold":0,"turn":"blocked","wx":"storm"},{"id":"e2234","day":59,"season":2,"sday":29,"kind":"ability","imp":2,"text":"Rook runs a whetstone and an oily rag over every blade at Frostspire. The crew drifts off to the sound of it.","heroes":["h15"],"parties":["p3"],"loc":"frostspire","skill":"evening_repairs","sk":"Evening Repairs","rule":true,"wx":"storm"},{"id":"e2250","day":59,"season":2,"sday":29,"kind":"talent","imp":1,"text":"Duren lays a tarp out at Frostspire and wraps up what the fight left behind. The undertaker in Ashfen will pay. Duren puts it down to Bodysnatcher.","heroes":["h3"],"parties":["p3"],"loc":"frostspire","skill":"bodysnatcher","wx":"storm"},{"id":"e2253","day":59,"season":2,"sday":29,"kind":"argument","imp":4,"text":"Pickles and Duren have had the same argument three times now. This time Pickles threw a boot. The Thunder of Frosthold is splitting into camps.","heroes":["h4","h3"],"parties":["p3"]},{"id":"e2280","day":60,"season":2,"sday":30,"kind":"road","imp":2,"text":"Rook follows a trail of crumbs from a gatepost pie to a farmhouse door by the road to Whitepeak Pass. An old baker answers, and is delighted someone asked.","heroes":["h15","h3","h4","h5"],"parties":["p3"],"road":"frostspire~whitepeak","road_rec":"r395"},{"id":"e2284","day":60,"season":2,"sday":30,"kind":"talent","imp":1,"text":"Rook makes everyone halt while they tighten a loose buckle on a stranger's pack. Somebody asks how. 'Evening Repairs,' says Rook.","heroes":["h15"],"parties":["p3"],"loc":"whitepeak","skill":"evening_repairs","wx":"storm"},{"id":"e2294","day":60,"season":2,"sday":30,"kind":"ledger","imp":2,"text":"Counters and coin this week: 4 sales, 473 silver changing hands. Biggest haul: Vex, 249 silver in Saltmarrow. Back up from the deep: The Thunder of Frosthold (2 days in Frostspire).","heroes":["h7","h5"],"parties":["p3"]},{"id":"e2298","day":60,"season":2,"sday":30,"kind":"goal_missed","imp":3,"text":"Not this time: The Thunder of Frosthold's goal (finish the season as one of the top three parties) falls short (finished 5th).","heroes":["h5","h3","h4","h15"],"parties":["p3"]},{"id":"e2343","day":61,"season":3,"sday":1,"kind":"party_life","imp":1,"text":"Pickles asks Rook if the view is nice up there. It is.","heroes":["h5","h3","h4","h15"],"parties":["p3"],"loc":"frosthold","wx":"storm"},{"id":"e2352","day":61,"season":3,"sday":1,"kind":"talent","imp":1,"text":"Duren keeps the marching pace with a song that just gets louder.","heroes":["h3"],"parties":["p3"],"loc":"whitepeak","skill":"crescendo","wx":"storm"},{"id":"e2370","day":62,"season":3,"sday":2,"kind":"party_life","imp":1,"text":"Pickles spends the whole road in the dust Rook kicks up, and says so.","heroes":["h5","h3","h4","h15"],"parties":["p3"],"loc":"whitepeak","wx":"snow"},{"id":"e2405","day":63,"season":3,"sday":3,"kind":"delve","imp":1,"text":"The Thunder of Frosthold descends into Frostspire, mostly unexplored (29%), map in hand.","heroes":["h5","h3","h4","h15"],"parties":["p3"],"loc":"frostspire","wx":"snow"},{"id":"e2406","day":63,"season":3,"sday":3,"kind":"fight","imp":2,"text":"The Thunder of Frosthold gets the better of 2 Ice Wraiths, a Yeti and a Frost Wolf in the hall of frozen explorers on floor 2 of Frostspire. Before Duren's Dissonance it could have gone either way. Ask the others what won it: Morwen's Plague. Loot: 10 pelts, 3 yeti steaks, 2 wolf haunches.","heroes":["h5","h3","h4","h15"],"parties":["p3"],"loc":"frostspire","fight":"f180","foes":["ice_wraith","yeti","frost_wolf"],"where":"in the hall of frozen explorers on floor 2 of Frostspire","won":true,"close":false,"shape":"plain","reworded":-9,"wx":"snow"},{"id":"e2407","day":63,"season":3,"sday":3,"kind":"fight","imp":1,"text":"In the steaming vent on floor 2 of Frostspire, 2 Ice Wraiths and a Frost Wolf get in the Thunder of Frosthold's way, briefly. The fight was over the moment Morwen's Shock landed on the ice wraith. Rook's Inspire turned the fight. Loot: 3 ectoplasm, 2 frost crystals, 3 wraith-frost.","heroes":["h5","h3","h4","h15"],"parties":["p3"],"loc":"frostspire","fight":"f181","foes":["ice_wraith","ice_wraith","frost_wolf"],"where":"in the steaming vent on floor 2 of Frostspire","won":true,"close":false,"shape":"place","reworded":-3,"wx":"snow"},{"id":"e2408","day":63,"season":3,"sday":3,"kind":"delve_day","imp":1,"text":"The Thunder of Frosthold works floor 2 of Frostspire at a steady pace: 3 rooms (the hall of frozen explorers, the steaming vent, the draught hole).","heroes":["h5","h3","h4","h15"],"parties":["p3"],"loc":"frostspire","pace":"steady","stats":{"rooms":3,"size":4,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":1,"unwalked":1,"fights":2,"close":0,"gear":["common"],"fears":0,"wild":[]},"wx":"snow"},{"id":"e2409","day":63,"season":3,"sday":3,"kind":"ability","imp":2,"text":"The forest floor grows a mattress for everyone in Morwen's party tonight. By morning the bruises are gone and nobody wants to get up.","heroes":["h5"],"parties":["p3"],"loc":"frostspire","skill":"bed_of_moss","sk":"Bed of Moss","rule":true,"wx":"snow"},{"id":"e2410","day":63,"season":3,"sday":3,"kind":"ability","imp":1,"text":"At Frostspire, Rook re-rivets Duren's pauldron and says nothing about how it got loose. Everyone sleeps easier.","heroes":["h15","h3"],"parties":["p3"],"loc":"frostspire","skill":"evening_repairs","sk":"Evening Repairs","rule":true,"wx":"snow"},{"id":"e2425","day":64,"season":3,"sday":4,"kind":"delve_day","imp":1,"text":"The Thunder of Frosthold works floor 2 of Frostspire at a steady pace: 1 room (the draught hole).","heroes":["h5","h3","h4","h15"],"parties":["p3"],"loc":"frostspire","pace":"steady","stats":{"rooms":1,"size":4,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":1,"unwalked":1,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]},"wx":"snow"},{"id":"e2426","day":64,"season":3,"sday":4,"kind":"delve_done","imp":1,"text":"The Thunder of Frosthold comes out after 2 days, and the first thing anyone wants is bread. They reached floor 2, cleared 2 rooms, found the hall of frozen explorers and turned back because the way on beat them twice, and they mean to come back with more.","heroes":["h5","h3","h4","h15"],"parties":["p3"],"loc":"frostspire","days":2,"bottom":false,"rooms":["the hall of frozen explorers"],"gold":0,"turn":"blocked","wx":"snow"},{"id":"e2427","day":64,"season":3,"sday":4,"kind":"ambush","imp":2,"text":"The Thunder of Frosthold, in fine spirits lately, sees off an Ice Wraith, a Yeti and a Frost Wolf at their camp outside Frostspire, in the middle of the night. Morwen's Nature's Wrath put poison in the yeti, and it did its slow work. Duren kept them off everyone with Inspire. Rook put the wounded ones out of their misery quickly. It's the decent thing. Loot: 3 ectoplasm, 2 frost crystals, 10 pelts.","heroes":["h5","h3","h4","h15"],"parties":["p3"],"loc":"frostspire","fight":"f183","foes":["ice_wraith","yeti","frost_wolf"],"where":"at their camp outside Frostspire, in the middle of the night","won":true,"close":false,"shape":"mood","reworded":-25,"wx":"snow"},{"id":"e2454","day":65,"season":3,"sday":5,"kind":"party_life","imp":3,"text":"Rook rides ahead, rides back, rides ahead again. Pickles is not amused.","heroes":["h5","h3","h4","h15"],"parties":["p3"],"loc":"frostspire","wx":"snow"},{"id":"e2467","day":65,"season":3,"sday":5,"kind":"gift","imp":2,"text":"The Troll's Tooth changes hands again: Morwen to Duren this time. It has been passed around this crew 2 times now.","heroes":["h5","h3"],"parties":["p3"],"loc":"whitepeak","wx":"snow"},{"id":"e2469","day":65,"season":3,"sday":5,"kind":"talent","imp":2,"text":"Duren pulls a handful of yarrow from a field edge and stuffs it in a pouch. 'For later. You'll see.'","heroes":["h3"],"parties":["p3"],"loc":"whitepeak","skill":"herbalism","wx":"snow"},{"id":"e2502","day":66,"season":3,"sday":6,"kind":"talent","imp":1,"text":"Rook spends a happy hour in Frosthold's ironmonger's, admiring rivets. The ironmonger offers him a stool.","heroes":["h15"],"parties":["p3"],"loc":"frosthold","skill":"evening_repairs","wx":"snow"},{"id":"e2523","day":67,"season":3,"sday":7,"kind":"party_life","imp":3,"text":"Pickles arrives at camp an hour behind Rook and finds the good spot by the fire taken.","heroes":["h5","h3","h4","h15"],"parties":["p3"],"loc":"frosthold","wx":"snow"},{"id":"e2543","day":67,"season":3,"sday":7,"kind":"campfire","imp":2,"text":"Duren saves Morwen the crispy bits from the pan without a word.","heroes":["h5","h3"],"parties":["p3"],"loc":"frosthold","wx":"snow"},{"id":"e2548","day":67,"season":3,"sday":7,"kind":"ledger","imp":2,"text":"THE LEDGER: 23 hauls sold this week, 1,338 silver in all. Biggest haul: Barnaby, 147 silver in Frosthold. Back up from the deep: The Thunder of Frosthold (2 days in Frostspire), Sunlit Quills (3 days in Thornmere Ruins).","heroes":["h19","h5","h11"],"parties":["p3","p2"]},{"id":"e2556","day":68,"season":3,"sday":8,"kind":"bounty","imp":2,"text":"The Thunder of Frosthold cashes in a season's worth of trophies at the Veldrock guild: about 71 silver a head.","heroes":["h5"],"parties":["p3"],"loc":"veldrock","amount":71,"wx":"snow"},{"id":"e2574","day":68,"season":3,"sday":8,"kind":"talent","imp":1,"text":"The Veldrock smith lends Rook the anvil for an hour and watches with professional jealousy. Field Forge: one of the things Rook learned the long way round.","heroes":["h15"],"parties":["p3"],"loc":"veldrock","skill":"field_forge","wx":"snow"},{"id":"e2575","day":68,"season":3,"sday":8,"kind":"talent","imp":2,"text":"A Veldrock street crowd learns the chorus to Pickles's newest song in one go.","heroes":["h4"],"parties":["p3"],"loc":"veldrock","skill":"packs_the_house","wx":"snow"},{"id":"e2599","day":69,"season":3,"sday":9,"kind":"boss_race","imp":3,"text":"Two crews, one boss. The Thunder of Frosthold and Juniper's Shields have both set out for Frostspire. The taverns are taking bets.","heroes":["h5","h3","h4","h15","h10","h12","h18"],"parties":["p3","p4"],"loc":"frostspire"},{"id":"e2630","day":70,"season":3,"sday":10,"kind":"ability","imp":2,"text":"Pickles plays a wet Tuesday at a Frosthold tavern to six people and a dog. By the last song there are sixty, and the dog is howling along. 37 silver in the hat.","heroes":["h4"],"parties":["p3"],"loc":"frosthold","skill":"packs_the_house","sk":"Packs the House","rule":true},{"id":"e2636","day":70,"season":3,"sday":10,"kind":"campfire","imp":1,"text":"Pickles writes Morwen a short poem about the road. Morwen pretends it's terrible and keeps it.","heroes":["h4","h5"],"parties":["p3"],"loc":"frosthold"},{"id":"e2644","day":71,"season":3,"sday":11,"kind":"ability","imp":1,"text":"Morwen camps alone at Whitepeak Pass, and the forest, with nobody else to fuss over, fusses over him: a moss pillow, a fern blanket, and every ache gone by morning.","heroes":["h5"],"parties":["p3"],"loc":"whitepeak","skill":"bed_of_moss","sk":"Bed of Moss","rule":true},{"id":"e2671","day":71,"season":3,"sday":11,"kind":"goal","imp":2,"text":"The Thunder of Frosthold's plan for the season, as told to the barkeep: to earn 550 silver between them before the season ends.","heroes":["h5","h3","h4"],"parties":["p3"]},{"id":"e2699","day":72,"season":3,"sday":12,"kind":"meet","imp":2,"text":"Ash and Morwen swap stories in Frostspire while Juniper's Shields and The Thunder of Frosthold swap rumours.","heroes":["h10","h12","h18","h5","h3","h4","h15"],"parties":["p4","p3"],"loc":"frostspire"},{"id":"e2720","day":73,"season":3,"sday":13,"kind":"delve","imp":1,"text":"The Thunder of Frosthold descends into Frostspire, partly explored (35%), map in hand.","heroes":["h5","h3","h4","h15"],"parties":["p3"],"loc":"frostspire"},{"id":"e2721","day":73,"season":3,"sday":13,"kind":"fight","imp":1,"text":"It's 2 Frost Wolves and an Ice Wraith against the Thunder of Frosthold in the buried trunks on floor 2 of Frostspire, and it isn't close. Crescendo caught three of them in one go. That was Duren. Loot: 5 pelts, 3 fangs & claws, 2 wolf haunches.","heroes":["h5","h3","h4","h15"],"parties":["p3"],"loc":"frostspire","fight":"f210","foes":["ice_wraith","frost_wolf","frost_wolf"],"where":"in the buried trunks on floor 2 of Frostspire","won":true,"close":false,"shape":"foe","reworded":-24},{"id":"e2722","day":73,"season":3,"sday":13,"kind":"fight","imp":1,"text":"The Thunder of Frosthold sees off 2 Ice Wraiths and a Yeti in the white chapel on floor 2 of Frostspire without much fuss. Ask anyone when it turned: Morwen's Nature's Wrath. Loot: 8 pelts, 3 yeti steaks, 6 ectoplasm.","heroes":["h5","h3","h4","h15"],"parties":["p3"],"loc":"frostspire","fight":"f211","foes":["yeti","ice_wraith","ice_wraith"],"where":"in the white chapel on floor 2 of Frostspire","won":true,"close":false,"shape":"plain","reworded":-18},{"id":"e2723","day":73,"season":3,"sday":13,"kind":"delve_day","imp":1,"text":"The Thunder of Frosthold works floor 2 of Frostspire at a push pace: 3 rooms (the buried trunks, the white chapel, the draught hole).","heroes":["h5","h3","h4","h15"],"parties":["p3"],"loc":"frostspire","pace":"push","stats":{"rooms":3,"size":4,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":1,"unwalked":1,"fights":2,"close":0,"gear":[],"fears":0,"wild":[]}},{"id":"e2738","day":74,"season":3,"sday":14,"kind":"delve_day","imp":1,"text":"The Thunder of Frosthold works floor 2 of Frostspire at a push pace: 1 room (the draught hole).","heroes":["h5","h3","h4","h15"],"parties":["p3"],"loc":"frostspire","pace":"push","stats":{"rooms":1,"size":4,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":1,"unwalked":1,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]}},{"id":"e2739","day":74,"season":3,"sday":14,"kind":"delve_done","imp":1,"text":"Frostspire, 2 days on: The Thunder of Frosthold comes up blinking at the daylight. They reached floor 2, cleared 2 rooms and turned back because the way on beat them twice, and they mean to come back with more.","heroes":["h5","h3","h4","h15"],"parties":["p3"],"loc":"frostspire","days":2,"bottom":false,"rooms":[],"gold":0,"turn":"blocked"},{"id":"e2740","day":74,"season":3,"sday":14,"kind":"ability","imp":2,"text":"The little travelling anvil comes out at Frostspire. By midnight Rook has fixed six straps, two helms and a boot.","heroes":["h15"],"parties":["p3"],"loc":"frostspire","skill":"evening_repairs","sk":"Evening Repairs","rule":true},{"id":"e2764","day":74,"season":3,"sday":14,"kind":"boss_race","imp":2,"text":"The Thunder of Frosthold drops out of the race for Hrimnir, Who Walks Under Snow. That leaves Juniper's Shields in it.","heroes":["h5","h3","h4","h15"],"parties":["p3"],"loc":"frostspire"},{"id":"e2777","day":74,"season":3,"sday":14,"kind":"ledger","imp":2,"text":"MARKET WEEK: 17 hauls sold across the realm, 2,136 silver all told. Biggest haul: Vex, 426 silver in Veldrock. Back up from the deep: The Thunder of Frosthold (2 days in Frostspire), Sunlit Quills (1 day in the Sunken Vault).","heroes":["h7","h5","h11"],"parties":["p3","p2"]},{"id":"e2792","day":75,"season":3,"sday":15,"kind":"talent","imp":2,"text":"Pickles packs Duren's bruised ribs with a warm comfrey poultice. Duren sleeps through the night. Poultices all the way, Pickles insists.","heroes":["h4","h3"],"parties":["p3"],"loc":"whitepeak","skill":"poultices"},{"id":"e2840","day":76,"season":3,"sday":16,"kind":"ability","imp":2,"text":"The Frosthold tavern is full before Pickles has tuned up, and nobody leaves before the third encore. 53 silver in the hat, and the crew sings along from the front table.","heroes":["h4"],"parties":["p3"],"loc":"frosthold","skill":"packs_the_house","sk":"Packs the House","rule":true},{"id":"e2845","day":76,"season":3,"sday":16,"kind":"campfire","imp":3,"text":"Morwen patches Pickles's cloak without being asked. Pickles pretends not to notice, then says thanks.","heroes":["h4","h5"],"parties":["p3"],"loc":"frosthold"},{"id":"e2857","day":77,"season":3,"sday":17,"kind":"party_life","imp":1,"text":"By the third crossroads Rook has stopped waiting and started complaining about the wait.","heroes":["h5","h3","h4","h15"],"parties":["p3"],"loc":"frosthold"},{"id":"e2873","day":77,"season":3,"sday":17,"kind":"gift","imp":2,"text":"Morwen admired Pickles's First Nail one too many times. Now it's Morwen's.","heroes":["h4","h5"],"parties":["p3"],"loc":"whitepeak"},{"id":"e2876","day":77,"season":3,"sday":17,"kind":"argument","imp":1,"text":"Duren says one thing too many about the correct way to sharpen a sword. Rook says two.","heroes":["h3","h15"],"parties":["p3"]},{"id":"e2893","day":78,"season":3,"sday":18,"kind":"party_life","imp":1,"text":"Rook waits at every crossroads for Pickles to catch up, and says nothing very loudly.","heroes":["h5","h3","h4","h15"],"parties":["p3"],"loc":"whitepeak"},{"id":"e2920","day":79,"season":3,"sday":19,"kind":"delve","imp":1,"text":"The Thunder of Frosthold descends into Frostspire, partly explored (35%), map in hand.","heroes":["h5","h3","h4","h15"],"parties":["p3"],"loc":"frostspire"},{"id":"e2925","day":79,"season":3,"sday":19,"kind":"fight","imp":2,"text":"With Morwen hitting hardest, the Thunder of Frosthold makes short work of 2 Yetis and a Frost Wolf in the sentry stair on floor 1 of Frostspire. Morwen's Nature's Wrath dropped two of them before they reached the line. Loot: 18 pelts, 2 frost crystals, 3 yeti steaks.","heroes":["h5","h3","h4","h15"],"parties":["p3"],"loc":"frostspire","fight":"f219","foes":["yeti","yeti","frost_wolf"],"where":"in the sentry stair on floor 1 of Frostspire","won":true,"close":false,"shape":"hero","reworded":-29},{"id":"e2926","day":79,"season":3,"sday":19,"kind":"fight","imp":2,"text":"In the windbreak on floor 1 of Frostspire, the Thunder of Frosthold sees off 2 Yetis, a Frost Wolf and an Ice Wraith. Duren cleared two of them with a single Dissonance. Loot: 19 pelts, 3 frost crystals, 6 yeti steaks.","heroes":["h5","h3","h4","h15"],"parties":["p3"],"loc":"frostspire","fight":"f220","foes":["yeti","frost_wolf","yeti"],"where":"in the windbreak on floor 1 of Frostspire","won":true,"close":false,"shape":"place","reworded":-1},{"id":"e2927","day":79,"season":3,"sday":19,"kind":"fight","imp":1,"text":"The Thunder of Frosthold, in fine spirits lately, dispatches an Ice Wraith, a Yeti and a Frost Wolf in the sentries' bunks on floor 2 of Frostspire. Rook's Frost Brand slowed the yeti to a crawl. Loot: 3 ectoplasm, 3 wraith-frost, 8 pelts.","heroes":["h5","h3","h4","h15"],"parties":["p3"],"loc":"frostspire","fight":"f221","foes":["ice_wraith","yeti","frost_wolf"],"where":"in the sentries' bunks on floor 2 of Frostspire","won":true,"close":false,"shape":"mood","reworded":-25},{"id":"e2929","day":79,"season":3,"sday":19,"kind":"fight","imp":1,"text":"It's 2 Ice Wraiths and a Frost Wolf against the Thunder of Frosthold in the cave behind the falls on floor 2 of Frostspire, and it isn't close. Everything after Duren's Dissonance went right. Loot: 6 ectoplasm, 4 frost crystals, 3 wraith-frost.","heroes":["h5","h3","h4","h15"],"parties":["p3"],"loc":"frostspire","fight":"f222","foes":["ice_wraith","ice_wraith","frost_wolf"],"where":"in the cave behind the falls on floor 2 of Frostspire","won":true,"close":false,"shape":"foe","reworded":-27},{"id":"e2930","day":79,"season":3,"sday":19,"kind":"delve_day","imp":1,"text":"The Thunder of Frosthold works floor 2 of Frostspire at a push pace: 5 rooms (the sentry stair, the windbreak, the sentries' bunks and 2 more).","heroes":["h5","h3","h4","h15"],"parties":["p3"],"loc":"frostspire","pace":"push","stats":{"rooms":5,"size":4,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":1,"unwalked":1,"fights":4,"close":0,"gear":["common"],"fears":0,"wild":[]}},{"id":"e2959","day":79,"season":3,"sday":19,"kind":"argument","imp":2,"text":"It starts with the ethics of looting bodies. It ends with Rook and Duren sleeping on opposite sides of the fire.","heroes":["h15","h3"],"parties":["p3"]},{"id":"e2968","day":79,"season":3,"sday":19,"kind":"big_move","imp":3,"text":"With Morwen hitting hardest, the Thunder of Frosthold makes short work of 2 Yetis and a Frost Wolf in the sentry stair on floor 1 of Frostspire. On the table: The Thunder of Frosthold +57 party renown (4th to 2nd among the crews).","heroes":["h5","h3","h4","h15"],"parties":["p3"],"party_moves":[{"party":"p3","gain":57,"from":4,"to":2}],"cause":"e2925","fight":"f219"},{"id":"e2970","day":80,"season":3,"sday":20,"kind":"delve_day","imp":1,"text":"The Thunder of Frosthold works floor 2 of Frostspire at a steady pace: 1 room (the draught hole).","heroes":["h5","h3","h4","h15"],"parties":["p3"],"loc":"frostspire","pace":"steady","stats":{"rooms":1,"size":4,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":1,"unwalked":1,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]}},{"id":"e2971","day":80,"season":3,"sday":20,"kind":"delve_done","imp":1,"text":"The Thunder of Frosthold comes out into the light after 2 days with the dark still in every seam. They made it to floor 2, found the cave behind the falls, took 4 rooms off the map's blank side, split 35 silver on the way up and turned back because the way on beat them twice, and they mean to come back with more.","heroes":["h5","h3","h4","h15"],"parties":["p3"],"loc":"frostspire","days":2,"bottom":false,"rooms":["the cave behind the falls"],"gold":35,"turn":"blocked"},{"id":"e2972","day":80,"season":3,"sday":20,"kind":"night","imp":2,"text":"Rook follows strange lights away from the camp outside Frostspire, gets thoroughly lost, and is found at dawn up a tree.","heroes":["h5","h3","h4","h15"],"parties":["p3"],"loc":"frostspire"},{"id":"e2998","day":80,"season":3,"sday":20,"kind":"argument","imp":1,"text":"Duren says one thing too many about the party's name. Rook says two.","heroes":["h3","h15"],"parties":["p3"]},{"id":"e3030","day":81,"season":3,"sday":21,"kind":"party_life","imp":1,"text":"Pickles asks Rook if the view is nice up there. It is.","heroes":["h5","h3","h4","h15"],"parties":["p3"],"loc":"frostspire"},{"id":"e3031","day":81,"season":3,"sday":21,"kind":"night","imp":1,"text":"A grey dwarf shares The Thunder of Frosthold's fire in Whitepeak Pass and swears on his beard there's a room in Frostspire nobody has opened. There isn't much beard left.","heroes":["h5","h3","h4","h15"],"parties":["p3"],"loc":"whitepeak"},{"id":"e3044","day":81,"season":3,"sday":21,"kind":"ledger","imp":2,"text":"Counters and coin this week: 19 sales, 1,334 silver changing hands. Biggest haul: Bramble, 265 silver in Carrbridge. Back up from the deep: The Thunder of Frosthold (2 days in Frostspire), The Coin of Thornwall (3 days in the Sunken Vault).","heroes":["h13","h5","h1"],"parties":["p3","p6"]},{"id":"e3090","day":82,"season":3,"sday":22,"kind":"argument","imp":1,"text":"Duren and Pickles are not speaking. It's about the party's name. It's never really about the party's name.","heroes":["h3","h4"],"parties":["p3"]},{"id":"e3091","day":82,"season":3,"sday":22,"kind":"campfire","imp":1,"text":"Morwen patches Rook's cloak without being asked. Rook pretends not to notice, then says thanks.","heroes":["h15","h5"],"parties":["p3"],"loc":"frosthold"},{"id":"e3097","day":82,"season":3,"sday":22,"kind":"vow_progress","imp":3,"text":"The Thunder of Frosthold swore to die rich on day 1 of season 2. With 3,316 silver earned since, they're rich. Now they just have to stay that way until the age ends.","heroes":["h5","h3","h4","h15"],"parties":["p3"],"cause":"e1264"},{"id":"e3098","day":82,"season":3,"sday":22,"kind":"goal_done","imp":4,"text":"GOAL: The Thunder of Frosthold set out to earn 550 silver between them before the season ends, and they have done it, with 8 days to spare. XP: Morwen +960, Duren +960, Pickles +960, Rook +800.","heroes":["h5","h3","h4","h15"],"parties":["p3"],"xp":{"h5":960,"h3":960,"h4":960,"h15":800}},{"id":"e3130","day":83,"season":3,"sday":23,"kind":"talent","imp":2,"text":"Duren works out the final chord of a new song. Morwen hums it all evening. Crescendo, the guild calls it.","heroes":["h3","h5"],"parties":["p3"],"loc":"whitepeak","skill":"crescendo"},{"id":"e3136","day":83,"season":3,"sday":23,"kind":"talent","imp":1,"text":"Pickles sings the whole way to keep the pace. Nobody admits it works.","heroes":["h4"],"parties":["p3"],"loc":"whitepeak","skill":"packs_the_house"},{"id":"e3161","day":84,"season":3,"sday":24,"kind":"ambush","imp":2,"text":"The Thunder of Frosthold dispatches 3 Frost Wolves and a Yeti on the road to Frostspire without much fuss. The last frost wolf takes off and isn't seen again. Two frost wolves went down together, and they have Duren's Crescendo to thank. Morwen saved Awaken the Grove for when it mattered. Duren was already counting the loot before the last one fell. Loot: 14 pelts, 7 fangs & claws, 4 wolf haunches.","heroes":["h5","h3","h4","h15"],"parties":["p3"],"loc":"whitepeak","fight":"f233","foes":["frost_wolf","frost_wolf","frost_wolf"],"where":"on the road to Frostspire","won":true,"close":false,"shape":"plain","reworded":-43,"wx":"snow"},{"id":"e3180","day":85,"season":3,"sday":25,"kind":"delve","imp":1,"text":"The Thunder of Frosthold descends into Frostspire, partly explored (35%), map in hand.","heroes":["h5","h3","h4","h15"],"parties":["p3"],"loc":"frostspire","wx":"snow"},{"id":"e3184","day":85,"season":3,"sday":25,"kind":"fight","imp":1,"text":"It's 2 Ice Wraiths and a Frost Wolf against the Thunder of Frosthold in the icicle porch on floor 1 of Frostspire, and it isn't close. Morwen closed it out with Shock on the ice wraith. Rook kept them off everyone with Inspire. Loot: 4 pelts, 2 wolf haunches, 3 wraith-frost.","heroes":["h5","h3","h4","h15"],"parties":["p3"],"loc":"frostspire","fight":"f235","foes":["frost_wolf","ice_wraith","ice_wraith"],"where":"in the icicle porch on floor 1 of Frostspire","won":true,"close":false,"shape":"foe","reworded":-25,"wx":"snow"},{"id":"e3185","day":85,"season":3,"sday":25,"kind":"fight","imp":1,"text":"Rook keeps everyone up as the Thunder of Frosthold beats 2 Ice Wraiths and a Frost Wolf in the ice-locked armoury on floor 1 of Frostspire. The final blow was Rook's Frost Brand. Loot: 3 ectoplasm, 1 frost crystal, 5 pelts.","heroes":["h5","h3","h4","h15"],"parties":["p3"],"loc":"frostspire","fight":"f236","foes":["ice_wraith","ice_wraith","frost_wolf"],"where":"in the ice-locked armoury on floor 1 of Frostspire","won":true,"close":false,"shape":"hero","reworded":-26,"wx":"snow"},{"id":"e3186","day":85,"season":3,"sday":25,"kind":"fight","imp":2,"text":"The Thunder of Frosthold, in fine spirits lately, defeats 2 Ice Wraiths, a Yeti and a Frost Wolf in the yeti dens on floor 2 of Frostspire. Rook swung Blasting Powder through two of them in one stroke. Loot: 4 frost crystals, 3 wraith-frost, 13 pelts.","heroes":["h5","h3","h4","h15"],"parties":["p3"],"loc":"frostspire","fight":"f237","foes":["ice_wraith","ice_wraith","yeti"],"where":"in the yeti dens on floor 2 of Frostspire","won":true,"close":false,"shape":"mood","reworded":-25,"wx":"snow"},{"id":"e3187","day":85,"season":3,"sday":25,"kind":"delve_day","imp":1,"text":"The Thunder of Frosthold works floor 2 of Frostspire at a push pace: 3 rooms (the icicle porch, the ice-locked armoury, the yeti dens).","heroes":["h5","h3","h4","h15"],"parties":["p3"],"loc":"frostspire","pace":"push","stats":{"rooms":3,"size":4,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":3,"close":0,"gear":[],"fears":0,"wild":[]},"wx":"snow"},{"id":"e3188","day":85,"season":3,"sday":25,"kind":"ambush","imp":2,"text":"The Thunder of Frosthold wakes to 2 Frost Wolves and an Ice Wraith in camp on floor 2 of Frostspire in the middle of the night, and sees them off. Rook ended it with Hammer Down. Morwen's Awaken the Grove turned the fight. Loot: 3 ectoplasm, 5 pelts, 2 fangs & claws.","heroes":["h5","h3","h4","h15"],"parties":["p3"],"loc":"frostspire","fight":"f238","foes":["ice_wraith","frost_wolf","frost_wolf"],"where":"at their camp on floor 2 of Frostspire, in the middle of the night","won":true,"close":false,"shape":"night","reworded":-12,"wx":"snow"},{"id":"e3194","day":85,"season":3,"sday":25,"kind":"talent","imp":1,"text":"Pickles makes sure everyone has a blanket before taking one. There aren't enough. She doesn't mention it.","heroes":["h4"],"parties":["p3"],"loc":"frostspire","skill":"heart_of_the_party","wx":"snow"},{"id":"e3232","day":86,"season":3,"sday":26,"kind":"delve_day","imp":1,"text":"The Thunder of Frosthold works floor 2 of Frostspire at a steady pace: 1 room (the draught hole).","heroes":["h5","h3","h4","h15"],"parties":["p3"],"loc":"frostspire","pace":"steady","stats":{"rooms":1,"size":4,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":1,"unwalked":1,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]},"wx":"snow"},{"id":"e3233","day":86,"season":3,"sday":26,"kind":"talent","imp":2,"text":"Duren tells Pickles a story about Pickles's home town that Pickles didn't know.","heroes":["h3","h4"],"parties":["p3"],"loc":"frostspire","skill":"old_stories","wx":"snow"},{"id":"e3234","day":86,"season":3,"sday":26,"kind":"ability","imp":2,"text":"Pickles lies down on a rock at camp. Morwen has a word with the rock. It is moss now, and Pickles sleeps like a baby.","heroes":["h5","h4"],"parties":["p3"],"loc":"frostspire","skill":"bed_of_moss","sk":"Bed of Moss","rule":true,"wx":"snow"},{"id":"e3258","day":87,"season":3,"sday":27,"kind":"delve_day","imp":1,"text":"The Thunder of Frosthold works floor 2 of Frostspire at a push pace: 1 room (the draught hole).","heroes":["h5","h3","h4","h15"],"parties":["p3"],"loc":"frostspire","pace":"push","stats":{"rooms":1,"size":4,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":1,"unwalked":1,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]},"wx":"snow"},{"id":"e3259","day":87,"season":3,"sday":27,"kind":"delve_done","imp":1,"text":"The Thunder of Frosthold climbs out at last, 3 days older and a good deal dirtier. They worked through 3 rooms, reached floor 2 and turned back because the way on beat them twice, and they mean to come back with more.","heroes":["h5","h3","h4","h15"],"parties":["p3"],"loc":"frostspire","days":3,"bottom":false,"rooms":[],"gold":0,"turn":"blocked","wx":"snow"},{"id":"e3273","day":87,"season":3,"sday":27,"kind":"talent","imp":1,"text":"Duren remembers a story about this very dungeon and the party skips a bad corridor. (The Old Stories, if anyone's asking.)","heroes":["h3"],"parties":["p3"],"loc":"frostspire","skill":"old_stories","wx":"snow"},{"id":"e3303","day":88,"season":3,"sday":28,"kind":"meet","imp":2,"text":"Morwen and Ash swap stories in Whitepeak Pass while The Thunder of Frosthold and Juniper's Shields swap rumours.","heroes":["h5","h3","h4","h15","h10","h12","h18"],"parties":["p3","p4"],"loc":"whitepeak","wx":"snow"},{"id":"e3304","day":88,"season":3,"sday":28,"kind":"ability","imp":2,"text":"A flock of starlings swirls over the road. Morwen reads them like a market board and tells Rook the price of fish three towns away.","heroes":["h5","h15"],"parties":["p3"],"loc":"whitepeak","skill":"word_on_the_wind","sk":"Word on the Wind","rule":true,"wx":"snow"},{"id":"e3314","day":88,"season":3,"sday":28,"kind":"ledger","imp":2,"text":"The week's trade: 21 packs emptied onto counters for 2,318 silver. Biggest haul: Vex, 245 silver in Veldrock. Back up from the deep: Juniper's Shields (3 days in Emberdeep), Sunlit Quills (2 days in the Sunken Vault), The Thunder of Frosthold (3 days in Frostspire), The Coin of Thornwall (3 days in the Sunken Vault).","heroes":["h7","h10","h11","h5"],"parties":["p4","p2","p3"]},{"id":"e3328","day":89,"season":3,"sday":29,"kind":"talent","imp":2,"text":"Morwen tells the Frosthold innkeeper the beds would be better stuffed with heather. The innkeeper tries it. They are.","heroes":["h5"],"parties":["p3"],"loc":"frosthold","skill":"bed_of_moss","wx":"snow"},{"id":"e3337","day":89,"season":3,"sday":29,"kind":"campfire","imp":2,"text":"Morwen gives Pickles the crust end of the loaf, which in some families is a declaration.","heroes":["h5","h4"],"parties":["p3"],"loc":"frosthold","wx":"snow"},{"id":"e3359","day":90,"season":3,"sday":30,"kind":"road","imp":3,"text":"The lanterns are blown out by a gust, and Rook helps Hetty Brimble walk the whole road to relight every one.","heroes":["h15","h3","h4","h5"],"parties":["p3"],"road":"frosthold~ironhaven","traveller":"hetty","road_rec":"r614"},{"id":"e3370","day":90,"season":3,"sday":30,"kind":"argument","imp":3,"text":"It starts with Morwen's cooking. It ends with Rook and Morwen sleeping on opposite sides of the fire.","heroes":["h15","h5"],"parties":["p3"]},{"id":"e3371","day":90,"season":3,"sday":30,"kind":"campfire","imp":1,"text":"Morwen hangs Pickles's wet socks by the fire with the care of someone hanging a tapestry.","heroes":["h5","h4"],"parties":["p3"],"loc":"frosthold","wx":"storm"},{"id":"e3383","day":90,"season":3,"sday":30,"kind":"vow_kept","imp":4,"text":"VOWS KEPT TO THE END OF THE AGE: The Scarlet Thorns, never to leave a companion behind (sworn in season 2); Sunlit Quills, that no one leaves this party (sworn in season 2); The Thunder of Frosthold, to die rich (sworn in season 2); The Tidal Ledger, to keep the peace: never draw first on another hero (sworn in season 2); Ash, to keep the peace: never draw first on another hero (sworn in season 1); Fenwick, never to pay a toll (sworn in season 1). Every one of them held.","heroes":["h12","h17"],"parties":["p1","p2","p3","p7"]}],"roles":{"h5":"Leader · Tracker","h4":"Face","h3":"Scout","h15":"Quartermaster"},"quest":{"what":"Head back to town","where":"Ironhaven","why":"packs full; Ironhaven pays about 375 silver more for the haul","floor":null,"floors":null},"tactics":{"front":["h15"],"back":["h5","h3","h4"],"plan":"Rook holds the front; Morwen casts from behind; Duren and Pickles pick off whatever gets close; Pickles keeps everyone standing.","traits":{"boldness":0.04,"risk":0.27,"greed":-0.1,"sociability":0.19,"honor":0.06,"curiosity":-0.1,"temper":0.3,"loyalty":-0.1},"mix":"2 talkers, 1 caster, 1 blade","notes":["One shield. If Rook falls, the line goes with him."],"style":["balanced"],"skills":[{"label":"Damage","skills":[{"hero":"h3","id":"crescendo","name":"Crescendo","desc":"The song builds and builds until the enemy can't hear themselves think.","tags":[],"rank":1,"uses":22},{"hero":"h5","id":"shock","name":"Shock","desc":"A crackle, a twitch, a lost turn.","tags":["storm"],"rank":1,"uses":19},{"hero":"h5","id":"natures_wrath","name":"Nature's Wrath","desc":"The forest fights back.","tags":["nature"],"rank":3,"uses":13},{"hero":"h3","id":"thorn_whip","name":"Thorn Whip","desc":"A vine with ideas.","tags":["nature"],"rank":2,"uses":11},{"hero":"h15","id":"frost_brand","name":"Frost Brand","desc":"The edge rimes with ice.","tags":["ice","arcane"],"rank":1,"uses":11},{"hero":"h4","id":"charged_trinket","name":"Charged Trinket","desc":"Throws something that was a teapot.","tags":["craft"],"rank":2,"uses":6},{"hero":"h3","id":"dissonance","name":"Dissonance","desc":"A chord no one should hear, and nobody fights well after it.","tags":["music"],"rank":2,"uses":5},{"hero":"h15","id":"hammer_down","name":"Hammer Down","desc":"Forging technique, applied to faces.","tags":["craft"],"rank":1,"uses":3},{"hero":"h15","id":"blasting_powder","name":"Blasting Powder","desc":"A pouch, a fuse, a short run.","tags":["craft","fire"],"rank":1,"uses":1},{"hero":"h3","id":"quick_shot","name":"Quick Shot","desc":"Two arrows before the first lands.","tags":[],"rank":1,"uses":0}]},{"label":"Healing","skills":[{"hero":"h4","id":"song_of_rest","name":"Song of Rest","desc":"A slow tune that knits the small cuts.","tags":["music","heal"],"rank":1,"uses":3}]},{"label":"Defence","skills":[{"hero":"h15","id":"inspire","name":"Inspire","desc":"A verse about how great they all are. Bruises feel smaller.","tags":["command"],"rank":3,"uses":29},{"hero":"h4","id":"spellsong","name":"Spellsong","desc":"Hums a tune that makes swords sharper.","tags":["music","arcane"],"rank":2,"uses":22},{"hero":"h3","id":"inspire","name":"Inspire","desc":"A verse about how great they all are. Bruises feel smaller.","tags":["command"],"rank":2,"uses":17},{"hero":"h4","id":"saga_of_fury","name":"Saga of Fury","desc":"Three verses, each angrier. Nobody waits for the fourth.","tags":["rage","music"],"rank":1,"uses":12},{"hero":"h5","id":"barkskin","name":"Barkskin","desc":"Skin goes knotted and brown. It's fine. It's fine.","tags":["nature","guard"],"rank":2,"uses":7},{"hero":"h4","id":"rousing_ballad","name":"Rousing Ballad","desc":"Four verses about how this all ends well.","tags":["music"],"rank":2,"uses":1},{"hero":"h3","id":"rousing_ballad","name":"Rousing Ballad","desc":"Four verses about how this all ends well.","tags":["music"],"rank":1,"uses":0}]},{"label":"Tricks","skills":[{"hero":"h5","id":"entangle","name":"Entangle","desc":"Roots burst from the floor.","tags":["nature"],"rank":2,"uses":13},{"hero":"h5","id":"awaken_the_grove","name":"Awaken the Grove","desc":"The trees were only waiting to be asked.","tags":["nature"],"rank":2,"uses":8},{"hero":"h5","id":"plague","name":"Plague","desc":"Everyone feels a bit off. Then very off.","tags":["death","nature"],"rank":1,"uses":5},{"hero":"h4","id":"shield_drum","name":"Shield Drum","desc":"Beats the shield before the charge. The charge arrives louder.","tags":["rage","music"],"rank":1,"uses":5},{"hero":"h4","id":"lullaby","name":"Lullaby","desc":"Sweet dreams, goblins.","tags":["music"],"rank":1,"uses":3},{"hero":"h3","id":"camouflage","name":"Camouflage","desc":"Becomes a bush. A suspicious bush.","tags":["stealth","nature"],"rank":1,"uses":0},{"hero":"h4","id":"tally_verse","name":"Tally Verse","desc":"Adds a line for every win. The crew fights to get a line.","tags":["rage","music"],"rank":1,"uses":0},{"hero":"h15","id":"plate_down","name":"Plate Down","desc":"Sets feet, sets jaw, and becomes furniture.","tags":[],"rank":1,"uses":0}]},{"label":"Always on","skills":[{"hero":"h3","id":"shoulder_to_shoulder","name":"Shoulder to Shoulder","desc":"Stands close enough to share a shield.","tags":["command"],"rank":1,"uses":0},{"hero":"h15","id":"honed_edge","name":"Honed Edge","desc":"Sharpened every night, without fail.","tags":["craft"],"rank":1,"uses":0},{"hero":"h15","id":"tempered_plate","name":"Tempered Plate","desc":"Armour they quenched themselves, twice.","tags":["craft"],"rank":3,"uses":0},{"hero":"h15","id":"perfect_edge","name":"Perfect Edge","desc":"Sharpened every night, named, and spoken to.","tags":["craft","crit"],"rank":1,"uses":0}]},{"label":"On the road","skills":[{"hero":"h5","id":"devout","name":"Devout","desc":"Temples patch them up for less.","tags":["holy"],"rank":1,"uses":0},{"hero":"h5","id":"whittler","name":"Whittling","desc":"Turns every stick into a small duck.","tags":[],"rank":1,"uses":0},{"hero":"h5","id":"tracker","name":"Tracker","desc":"Reads a broken twig like a letter.","tags":["nature","beast"],"rank":1,"uses":0},{"hero":"h5","id":"forager","name":"Forager","desc":"Finds dinner and herbs on any trail.","tags":["nature"],"rank":2,"uses":0},{"hero":"h5","id":"wild_tongue","name":"Wild Tongue","desc":"Asks the birds. The birds know a shortcut.","tags":["nature"],"rank":1,"uses":0},{"hero":"h5","id":"spice_box","name":"Spice Box","desc":"Carries a tin of spices the size of a hymnal, and uses it.","tags":[],"rank":1,"uses":0},{"hero":"h5","id":"compost_heap","name":"Compost Heap","desc":"Everything dead becomes something growing. Usually lettuce.","tags":["death","nature"],"rank":2,"uses":0},{"hero":"h3","id":"cartography","name":"Cartography","desc":"Draws the map as they walk it.","tags":["travel"],"rank":1,"uses":0},{"hero":"h3","id":"omens","name":"Omens","desc":"Reads crows, bones and the bottom of the cup.","tags":["death","arcane"],"rank":1,"uses":0},{"hero":"h3","id":"pathfinding","name":"Pathfinding","desc":"Knows the back ways.","tags":["travel","nature"],"rank":3,"uses":0},{"hero":"h3","id":"bodysnatcher","name":"Bodysnatcher","desc":"Has a cart, a tarp, and no questions.","tags":["death"],"rank":2,"uses":0},{"hero":"h3","id":"game_hunter","name":"Game Hunter","desc":"Comes back from a short walk with dinner.","tags":["nature","beast"],"rank":1,"uses":0},{"hero":"h3","id":"herbalism","name":"Herbalism","desc":"Knows every useful leaf.","tags":["nature","heal"],"rank":1,"uses":0},{"hero":"h3","id":"tracker","name":"Tracker","desc":"Reads a broken twig like a letter.","tags":["nature","beast"],"rank":1,"uses":0},{"hero":"h4","id":"sword_dancer","name":"Sword Dancer","desc":"Dances with steel. Still has all ten toes.","tags":["crit","music"],"rank":1,"uses":0},{"hero":"h4","id":"bookkeeper","name":"Bookkeeping","desc":"Every copper accounted for.","tags":["trade"],"rank":1,"uses":0},{"hero":"h4","id":"bedside_manner","name":"Bedside Manner","desc":"Makes you feel better before the medicine does.","tags":["heal"],"rank":1,"uses":0},{"hero":"h4","id":"poultices","name":"Poultices","desc":"Mashes leaves. Wounds close.","tags":["heal","nature"],"rank":1,"uses":0},{"hero":"h4","id":"letter_writer","name":"Letter Writer","desc":"Writes home. Writes everyone's home.","tags":["lore"],"rank":1,"uses":0},{"hero":"h4","id":"campfire_chorus","name":"Campfire Chorus","desc":"Teaches the crew a round. The crew sings it wrong, together.","tags":["music"],"rank":3,"uses":0},{"hero":"h15","id":"farrier","name":"Farrier","desc":"Shoes horses, mends wheels, and charges the crew nothing.","tags":["ride","craft"],"rank":1,"uses":0},{"hero":"h15","id":"bird_caller","name":"Bird Caller","desc":"Whistles. Something whistles back.","tags":["beast","nature"],"rank":1,"uses":0},{"hero":"h15","id":"armour_fitting","name":"Armour Fitting","desc":"Knows what a breastplate should cost. Pays exactly that.","tags":["craft"],"rank":1,"uses":0},{"hero":"h15","id":"hand_signs","name":"Hand Signs","desc":"Can say 'goblins, three, left' without a sound.","tags":["stealth"],"rank":1,"uses":0},{"hero":"h15","id":"whetstone","name":"Whetstone","desc":"Sharpens everything. Has been asked to stop.","tags":["craft"],"rank":2,"uses":0},{"hero":"h15","id":"field_forge","name":"Field Forge","desc":"Sets up an anvil on any flat rock and mends what the road broke.","tags":["craft"],"rank":1,"uses":0},{"hero":"h15","id":"fletcher","name":"Fletcher","desc":"Every arrow straight, every feather matched.","tags":["craft","crit"],"rank":1,"uses":0}]}],"share":[{"hero":"h5","dmg":2366,"healed":0,"taken":42,"kills":15,"row":"back"},{"hero":"h3","dmg":4728,"healed":147,"taken":35,"kills":22,"row":"back"},{"hero":"h4","dmg":0,"healed":170,"taken":139,"kills":0,"row":"back"},{"hero":"h15","dmg":1334,"healed":397,"taken":769,"kills":8,"row":"front"}],"ground":{"name":"Frostspire","fights":20}},"trophies":[{"boss":"The Silk Matriarch","monster":"spider_queen","place":"The Collapsed Mine","day":16,"season":1,"fight":"f53"}]};